module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg        clk;
    reg        resetn;
    reg  [1:0] byteena;
    reg  [15:0] d;
    wire [15:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .resetn(resetn),
        .byteena(byteena),
        .d(d),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;
    reg [15:0] expected_q;

    // Task to check outputs using 4-state case inequality
    task check_output(input [15:0] exp);
        begin
            #1; // small delay after clock edge to sample stable output
            if (q !== exp) begin
                $display("Time %0t: Mismatch! d=%h, byteena=%b, q=%h, expected=%h", 
                         $time, d, byteena, q, exp);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        resetn = 0;
        byteena = 2'b00;
        d = 16'h0000;
        expected_q = 16'h0000;

        // Apply reset
        #12;
        resetn = 1;
        check_output(expected_q);

        // Test 1: Write both bytes (byteena = 2'b11)
        @(posedge clk);
        d = 16'hA55A;
        byteena = 2'b11;
        expected_q = 16'hA55A;
        check_output(expected_q);

        // Test 2: Write upper byte only (byteena = 2'b10), lower byte should hold
        @(posedge clk);
        d = 16'h1234;
        byteena = 2'b10;
        expected_q = 16'h125A;
        check_output(expected_q);

        // Test 3: Write lower byte only (byteena = 2'b01), upper byte should hold
        @(posedge clk);
        d = 16'hABCD;
        byteena = 2'b01;
        expected_q = 16'h12CD;
        check_output(expected_q);

        // Test 4: Write neither byte (byteena = 2'b00), both bytes should hold
        @(posedge clk);
        d = 16'hFFFF;
        byteena = 2'b00;
        expected_q = 16'h12CD;
        check_output(expected_q);

        // Test 5: Synchronous active-low reset test
        @(posedge clk);
        resetn = 0;
        byteena = 2'b11;
        d = 16'hFFFF;
        expected_q = 16'h0000;
        check_output(expected_q);

        // Release reset and write partial again
        @(posedge clk);
        resetn = 1;
        byteena = 2'b11;
        d = 16'h8765;
        expected_q = 16'h8765;
        check_output(expected_q);

        // Final status report
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
